ALTER TABLE public.articles ADD COLUMN categories text[] NOT NULL DEFAULT '{}'; UPDATE public.articles SET categories = ARRAY[category] WHERE categories = '{}'; ALTER TABLE public.articles ADD COLUMN is_editors_pick boolean NOT NULL DEFAULT false; CREATE TABLE public.article_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), article_id uuid NOT NULL REFERENCES public.articles(id) ON DELETE CASCADE, viewed_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX article_views_article_viewed ON public.article_views (article_id, viewed_at DESC); GRANT INSERT ON public.article_views TO anon, authenticated; GRANT SELECT ON public.article_views TO authenticated; GRANT ALL ON public.article_views TO service_role; ALTER TABLE public.article_views ENABLE ROW LEVEL SECURITY; CREATE POLICY "Anyone can record a view" ON public.article_views FOR INSERT TO anon, authenticated WITH CHECK (true); CREATE POLICY "Admins can view stats" ON public.article_views FOR SELECT TO authenticated USING (private.has_role(auth.uid(), 'admin'::app_role));